import{_ as e}from"./chunks/3.DCMEIqLO.js";import{u as t}from"./chunks/useReporter.D4n0v9NN.js";import{c as a,o as l,b2 as o}from"./chunks/framework.BRCYMVIo.js";const i="/assets/4.O_l2ZdLl.png",s="/assets/1.BrOBph5r.png",r="/assets/2.BRXfuQ9G.png",d=o('<p>Mac 的磁盘空间经常不是被某一个大文件占满，而是慢慢堆积在应用缓存、浏览器缓存、日志、临时文件和已经卸载的软件残留中。macOS 自带的「储存空间」可以查看大致分类，却很难继续定位和清理体积庞大的「系统数据」。</p><p>这篇文章介绍一套免费开源的解决方案：使用 <strong>Mole</strong> 负责扫描和清理，再通过 <strong>MoleUI</strong> 提供图形界面。实测清理前后，系统已用空间从 <code>469.52 GB</code> 降到 <code>430.56 GB</code>，释放了约 <strong>38.96 GB</strong>。</p><div class="warning custom-block"><p class="custom-block-title">清理前请先确认</p><p>系统清理会删除缓存、日志和临时文件。重要数据应提前备份，开始清理前关闭正在运行的应用，并逐项检查扫描结果。无法确认用途的目录，不要勾选。</p></div><h2 id="为什么需要第三方清理工具" tabindex="-1">为什么需要第三方清理工具 <a class="header-anchor" href="#为什么需要第三方清理工具" aria-label="Permalink to &quot;为什么需要第三方清理工具&quot;">​</a></h2><p>常见的 Mac 清理软件通常采用订阅制，免费版本只能扫描，真正执行清理时仍然需要付费。以 CleanMyMac 为例，其清理、应用卸载和性能维护等功能被划分到不同的付费方案中。</p><p><img src="'+i+'" alt="CleanMyMac 付费方案页面"></p><p>付费软件的优势通常是界面成熟、操作简单，但如果需求只是查看磁盘占用、清理缓存和卸载残留，开源工具已经可以覆盖大部分场景。</p><h2 id="免费方案-mole-与-moleui" tabindex="-1">免费方案：Mole 与 MoleUI <a class="header-anchor" href="#免费方案-mole-与-moleui" aria-label="Permalink to &quot;免费方案：Mole 与 MoleUI&quot;">​</a></h2><p><a href="https://github.com/tw93/Mole" target="_blank" rel="noreferrer">Mole</a> 是一款运行在终端中的开源 macOS 系统维护工具，能够完成深度清理、应用卸载、磁盘分析、系统优化和状态监控。它使用 GPL-3.0 协议开源，清理过程在本机执行。</p><p><a href="https://github.com/Zhili1004/MoleUI" target="_blank" rel="noreferrer">MoleUI</a> 是 Mole 的第三方图形界面，将扫描结果按类别、大小和勾选状态展示出来，更适合不熟悉命令行的用户。MoleUI 已内置 Mole，不需要提前安装命令行版本，并提供适用于 Intel 和 Apple Silicon 的通用安装包。</p><div class="info custom-block"><p class="custom-block-title">注意项目之间的区别</p><ul><li><code>tw93/Mole</code>：免费开源的官方命令行工具；</li><li><code>Zhili1004/MoleUI</code>：免费开源的独立社区图形界面，底层调用 Mole；</li><li><a href="https://mole.fit" target="_blank" rel="noreferrer">Mole for Mac</a>：Mole 作者提供的商业图形应用，不是本文使用的 MoleUI。</li></ul></div><p>MoleUI 目前包含以下主要功能：</p><table tabindex="0"><thead><tr><th>功能</th><th>用途</th></tr></thead><tbody><tr><td>Clean</td><td>扫描系统缓存、应用缓存、日志、临时文件和废纸篓</td></tr><tr><td>Uninstall</td><td>卸载应用并查找关联的配置与残留文件</td></tr><tr><td>Optimize</td><td>刷新缓存与部分系统服务</td></tr><tr><td>Analyze</td><td>分析磁盘目录和大文件占用</td></tr><tr><td>Status</td><td>查看 CPU、内存、磁盘和网络状态</td></tr><tr><td>Touch ID</td><td>为需要管理员权限的操作提供系统授权</td></tr></tbody></table><p><img src="'+e+`" alt="MoleUI 系统清理界面"></p><h2 id="下载与安装" tabindex="-1">下载与安装 <a class="header-anchor" href="#下载与安装" aria-label="Permalink to &quot;下载与安装&quot;">​</a></h2><p>本文使用的是 MoleUI 图形版，安装过程如下：</p><ol><li>打开 <a href="https://github.com/Zhili1004/MoleUI/releases/latest" target="_blank" rel="noreferrer">MoleUI Releases</a>；</li><li>下载名称中包含 <code>universal.dmg</code> 的安装包；</li><li>打开 DMG，将 MoleUI 拖入「应用程序」目录；</li><li>启动 MoleUI，等待首次扫描完成。</li></ol><p>项目说明中标注的最低系统版本为 macOS 11，并且安装包已签名和公证。为避免下载到被修改的副本，建议只从 GitHub 项目的 Releases 页面获取安装包。</p><p>如果更习惯终端，也可以直接安装 Mole：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mole</span></span></code></pre></div><p>安装后先通过 <code>--dry-run</code> 预览将要清理的内容，再决定是否执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --dry-run</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span></span></code></pre></div><p>通过 Homebrew 安装时，项目当前建议使用 macOS 14 或更高版本；较旧系统可以参考 Mole 仓库中的脚本安装方式。</p><h2 id="使用-moleui-清理空间" tabindex="-1">使用 MoleUI 清理空间 <a class="header-anchor" href="#使用-moleui-清理空间" aria-label="Permalink to &quot;使用 MoleUI 清理空间&quot;">​</a></h2><h3 id="_1-扫描可清理内容" tabindex="-1">1. 扫描可清理内容 <a class="header-anchor" href="#_1-扫描可清理内容" aria-label="Permalink to &quot;1. 扫描可清理内容&quot;">​</a></h3><p>打开左侧的 <strong>Clean</strong>，MoleUI 会扫描缓存、日志、临时文件等内容，并在每个类别右侧显示预计可释放的空间。</p><p>本次扫描中，占用最大的项目是 <code>System Caches</code>，约为 <code>34.69 GB</code>；浏览器缓存约为 <code>1.76 GB</code>。两项已经占到本次可清理空间的绝大部分。</p><h3 id="_2-检查清理项目" tabindex="-1">2. 检查清理项目 <a class="header-anchor" href="#_2-检查清理项目" aria-label="Permalink to &quot;2. 检查清理项目&quot;">​</a></h3><p>不要看到较大的数字就直接全部清理，建议特别检查以下内容：</p><ul><li>浏览器缓存：清理后网页资源需要重新下载，首次打开网站可能变慢；</li><li>应用缓存：部分应用下次启动时会重新生成索引或缓存；</li><li>开发工具缓存：Xcode、Node.js、npm、pnpm、Gradle 等缓存可能很大，但重新构建时需要再次下载；</li><li>废纸篓：清空后无法通过废纸篓恢复文件；</li><li>邮件缓存：可能触发邮件内容或附件重新同步。</li></ul><p>确认后再点击 <strong>Start Cleanup</strong>。涉及系统目录时，macOS 会弹出系统授权窗口；只应在确认操作来自 MoleUI 时授权。</p><h3 id="_3-清理后重新检查" tabindex="-1">3. 清理后重新检查 <a class="header-anchor" href="#_3-清理后重新检查" aria-label="Permalink to &quot;3. 清理后重新检查&quot;">​</a></h3><p>清理完成后，回到「系统设置 → 通用 → 储存空间」查看结果。macOS 会在后台重新统计各类空间，因此分类数字可能需要等待一段时间才会稳定。</p><h2 id="测试效果" tabindex="-1">测试效果 <a class="header-anchor" href="#测试效果" aria-label="Permalink to &quot;测试效果&quot;">​</a></h2><p>清理前，磁盘共 <code>494.38 GB</code>，已使用 <code>469.52 GB</code>，其中「系统数据」占用 <code>163.38 GB</code>。</p><p><img src="`+s+'" alt="清理前的 macOS 储存空间"></p><p>清理后，已使用空间下降到 <code>430.56 GB</code>，「系统数据」下降到 <code>124.07 GB</code>。</p><p><img src="'+r+'" alt="清理后的 macOS 储存空间"></p><table tabindex="0"><thead><tr><th>对比项</th><th style="text-align:right;">清理前</th><th style="text-align:right;">清理后</th><th style="text-align:right;">变化</th></tr></thead><tbody><tr><td>已使用空间</td><td style="text-align:right;">469.52 GB</td><td style="text-align:right;">430.56 GB</td><td style="text-align:right;">减少 38.96 GB</td></tr><tr><td>系统数据</td><td style="text-align:right;">163.38 GB</td><td style="text-align:right;">124.07 GB</td><td style="text-align:right;">减少 39.31 GB</td></tr></tbody></table><p>这次清理释放了约 <strong>39 GB</strong> 空间，结果与 MoleUI 扫描出的缓存体积基本一致。需要注意，macOS 会动态调整「系统数据」「macOS」和「应用程序」的归类，分类差值不一定等于实际释放空间；判断效果时，应优先比较磁盘的总已用空间。</p><h2 id="安全使用建议" tabindex="-1">安全使用建议 <a class="header-anchor" href="#安全使用建议" aria-label="Permalink to &quot;安全使用建议&quot;">​</a></h2><p>Mole 和 MoleUI 的源码公开并不代表每一项都适合无条件删除。清理工具的风险来自删除行为本身，建议遵循下面几条原则：</p><ol><li>第一次使用时只清理明确可重建的缓存和日志，不处理不认识的目录；</li><li>清理前退出浏览器、开发工具和其他正在写入数据的应用；</li><li>重要项目、照片和文档应有独立备份，清理工具不能替代备份；</li><li>使用命令行版时，先运行 <code>mo clean --dry-run</code>，再用 <code>mo history</code> 查看历史操作；</li><li>如果空间主要被照片、视频、虚拟机或项目依赖占用，应先使用 <code>Analyze</code> 定位，而不是反复清理系统缓存。</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>如果希望免费清理 Mac，又不想直接操作终端，MoleUI 是一个容易上手的选择；如果更看重更新速度、可审查的命令和精细控制，则可以直接使用 Mole 命令行版。</p><p>这类工具最适合处理长期积累的缓存、日志和卸载残留，不适合把所有扫描结果都当作“垃圾”。先预览、再筛选、最后清理，通常比追求一次释放最多空间更稳妥。</p>',46),n=[d],b=JSON.parse('{"title":"免费开源的 Mac 清理工具：Mole 与 MoleUI 使用体验","description":"介绍免费开源的 Mac 清理工具 Mole 与图形界面 MoleUI，包括下载安装、清理步骤、安全注意事项和释放约 39 GB 空间的实测结果。","frontmatter":{"title":"免费开源的 Mac 清理工具：Mole 与 MoleUI 使用体验","head":[["meta",{"name":"description","content":"介绍免费开源的 Mac 清理工具 Mole 与图形界面 MoleUI，包括下载安装、清理步骤、安全注意事项和释放约 39 GB 空间的实测结果。"}],["meta",{"name":"keywords","content":"Mac清理工具,Mole,MoleUI,macOS系统数据,磁盘清理,免费开源软件"}]],"layout":"doc","outline":"deep"},"headers":[],"relativePath":"tools/Mac-Cleaner.md","filePath":"tools/Mac-Cleaner.md","lastUpdated":null}'),c={name:"tools/Mac-Cleaner.md"},k=Object.assign(c,{setup(h){return t(),(p,m)=>(l(),a("div",null,n))}});export{b as __pageData,k as default};
